<section class="vc-grid four" aria-label="Sustainability summary"><article class="vc-card vc-stat"><span class="vc-stat-label">Profile completion</span><div class="vc-stat-value">72%</div><div class="vc-progress"><span style="width:72%"></span></div></article><article class="vc-card vc-stat"><span class="vc-stat-label">Verified claims</span><div class="vc-stat-value">18</div><div class="vc-stat-note">Across 14 products</div></article><article class="vc-card vc-stat"><span class="vc-stat-label">Claims needing evidence</span><div class="vc-stat-value">3</div><div class="vc-stat-note">Not public until approved</div></article><article class="vc-card vc-stat"><span class="vc-stat-label">Credentials expiring</span><div class="vc-stat-value">2</div><div class="vc-stat-note">Within 90 days</div></article></section>
<div class="vc-callout warning mt-3"><strong>Claims integrity:</strong> do not use vague statements such as “100% eco-friendly” or “zero impact.” State exactly what is better, the measured scope, reporting period, evidence, limitations and disposal conditions.</div>
<div data-tabs class="mt-3"><div class="vc-tabs"><button class="vc-tab active" type="button" data-tab-target="commitments">Vendor commitments</button><button class="vc-tab" type="button" data-tab-target="claims">Claims & evidence</button><button class="vc-tab" type="button" data-tab-target="packaging">Packaging</button><button class="vc-tab" type="button" data-tab-target="impact">Impact data</button></div>
<section data-tab-panel="commitments"><form class="vc-card" data-frontend-form="sustainability-profile" data-success="Sustainability profile validated. Backend review is required before publication."><div class="vc-card-head"><h2>Public sustainability and ethical sourcing profile</h2><span class="vc-status warning">Draft</span></div><div class="vc-card-body"><div class="vc-form-grid"><div class="vc-field full"><label for="sustainability-statement">Public sustainability statement *</label><textarea class="vc-textarea" id="sustainability-statement" name="sustainability_statement" required minlength="80" maxlength="1500" placeholder="Describe materials, production, people, packaging, current limitations and measurable commitments."></textarea></div><div class="vc-field"><label for="sourcing-radius">Typical local sourcing radius (km)</label><input class="vc-input" id="sourcing-radius" name="sourcing_radius_km" type="number" min="0" max="5000"></div><div class="vc-field"><label for="local-material-share">Materials sourced within India (%) *</label><input class="vc-input" id="local-material-share" name="india_sourced_percent" type="number" min="0" max="100" step="0.1" required></div><div class="vc-field"><label for="artisan-count">Artisans/workers supported *</label><input class="vc-input" id="artisan-count" name="artisan_count" type="number" min="1" max="100000" required></div><div class="vc-field"><label for="wage-practice">Wage/payment practice *</label><select class="vc-select" id="wage-practice" name="wage_practice" required><option value="">Select practice</option><option>Documented living-wage benchmark</option><option>Applicable statutory wage or above</option><option>Piece-rate with documented minimum guarantee</option><option>Member-owned cooperative revenue share</option><option>Owner-operated artisan business</option></select></div><div class="vc-field"><label for="energy-source">Primary production energy source *</label><select class="vc-select" id="energy-source" name="energy_source" required><option value="">Select source</option><option>Grid electricity</option><option>On-site solar</option><option>Purchased renewable electricity</option><option>Primarily manual production</option><option>Mixed sources</option></select></div><div class="vc-field"><label for="renewable-share">Renewable energy share (%)</label><input class="vc-input" id="renewable-share" name="renewable_energy_percent" type="number" min="0" max="100" step="0.1"></div><div class="vc-field full"><label for="water-practice">Water use and wastewater practice *</label><textarea class="vc-textarea" id="water-practice" name="water_practice" required minlength="20" maxlength="800"></textarea></div><div class="vc-field full"><label for="waste-practice">Material waste and hazardous-waste practice *</label><textarea class="vc-textarea" id="waste-practice" name="waste_practice" required minlength="20" maxlength="800"></textarea></div><div class="vc-field full"><label class="vc-check"><input name="code_of_conduct" type="checkbox" required> I confirm that public claims are accurate, evidence-backed, reviewed when circumstances change, and do not hide material limitations.</label></div></div><div class="vc-form-actions"><button class="vc-btn" type="button" data-demo-action="Preview public sustainability profile">Preview</button><button class="vc-btn primary" type="submit">Validate profile</button></div></div></form></section>
<section data-tab-panel="claims" hidden><div class="vc-card"><div class="vc-card-head"><div><h2>Environmental and social claims register</h2><span class="vc-help">A claim is published only after its evidence and wording are approved.</span></div><button class="vc-btn primary" type="button" data-open-dialog="claim-dialog">Add claim</button></div><div class="vc-table-wrap"><table class="vc-table"><thead><tr><th>Claim</th><th>Scope</th><th>Evidence</th><th>Valid until</th><th>Review status</th><th>Public status</th><th>Action</th></tr></thead><tbody><tr><td><b>60% recycled cotton</b></td><td>Handloom cushion range</td><td>GOTS-IND-22014</td><td>30 Jun 2027</td><td><span class="vc-status success">Verified</span></td><td><span class="vc-status success">Published</span></td><td><button class="vc-btn small" type="button" data-demo-action="Review sustainability claim">Review</button></td></tr><tr><td><b>Plastic-free packaging</b></td><td>All orders</td><td>Packaging declaration + invoices</td><td>Review annually</td><td><span class="vc-status warning">Evidence requested</span></td><td><span class="vc-status info">Hidden</span></td><td><button class="vc-btn small" type="button" data-open-dialog="claim-dialog">Complete</button></td></tr><tr><td><b>Locally sourced clay</b></td><td>Blue pottery</td><td>Supplier declarations</td><td>31 Mar 2027</td><td><span class="vc-status info">Under review</span></td><td><span class="vc-status info">Hidden</span></td><td><button class="vc-btn small" type="button" data-demo-action="View claim review status">Status</button></td></tr></tbody></table></div></div></section>
<section data-tab-panel="packaging" hidden><form class="vc-card" data-frontend-form="sustainable-packaging" data-success="Packaging data validated."><div class="vc-card-head"><h2>Default sustainable packaging</h2></div><div class="vc-card-body"><div class="vc-form-grid"><div class="vc-field"><label for="default-pack-material">Primary packaging material *</label><input class="vc-input" id="default-pack-material" name="packaging_material" required maxlength="160"></div><div class="vc-field"><label for="pack-recycled-share">Verified recycled content (%)</label><input class="vc-input" id="pack-recycled-share" name="packaging_recycled_percent" type="number" min="0" max="100" step="0.1"></div><div class="vc-field"><label for="default-pack-weight">Default packaging weight (grams) *</label><input class="vc-input" id="default-pack-weight" name="packaging_weight" type="number" min="1" max="100000" required></div><div class="vc-field"><label for="packaging-supplier">Packaging supplier/reference</label><input class="vc-input" id="packaging-supplier" name="packaging_supplier" maxlength="160"></div><div class="vc-field full"><label class="vc-check"><input name="plastic_free" type="checkbox"> Plastic-free including tape, filler, coating and labels</label><label class="vc-check mt-2"><input name="recyclable" type="checkbox"> Recyclable in commonly available Indian waste streams</label><label class="vc-check mt-2"><input name="reusable" type="checkbox"> Designed for reuse</label><label class="vc-check mt-2"><input name="compostable" type="checkbox"> Compostable under clearly stated conditions</label></div><div class="vc-field full"><label for="pack-disposal">Customer disposal/reuse instructions *</label><textarea class="vc-textarea" id="pack-disposal" name="disposal_instructions" required minlength="20" maxlength="800"></textarea></div><div class="vc-field full"><label for="pack-proof">Supplier specification or packaging evidence</label><input class="vc-input" id="pack-proof" name="packaging_evidence" type="file" accept="image/jpeg,image/png,application/pdf" data-max-bytes="5242880"></div></div><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Validate packaging profile</button></div></div></form></section>
<section data-tab-panel="impact" hidden><form class="vc-card" data-frontend-form="impact-report" data-success="Impact reporting fields validated. Figures remain unpublished until evidence is reviewed."><div class="vc-card-head"><h2>Measured impact reporting</h2><span class="vc-status info">Optional but evidence-based</span></div><div class="vc-card-body"><div class="vc-form-grid"><div class="vc-field"><label for="impact-start">Reporting period start *</label><input class="vc-input" id="impact-start" name="period_start" type="date" required></div><div class="vc-field"><label for="impact-end">Reporting period end *</label><input class="vc-input" id="impact-end" name="period_end" type="date" required></div><div class="vc-field"><label for="impact-units">Units produced *</label><input class="vc-input" id="impact-units" name="units_produced" type="number" min="1" max="100000000" required></div><div class="vc-field"><label for="impact-local">Locally/India-sourced materials (%)</label><input class="vc-input" id="impact-local" name="local_material_percent" type="number" min="0" max="100" step="0.1"></div><div class="vc-field"><label for="impact-recycled">Recycled/upcycled material used (kg)</label><input class="vc-input" id="impact-recycled" name="recycled_material_kg" type="number" min="0" max="10000000" step="0.01"></div><div class="vc-field"><label for="impact-waste">Waste reused/diverted (kg)</label><input class="vc-input" id="impact-waste" name="waste_diverted_kg" type="number" min="0" max="10000000" step="0.01"></div><div class="vc-field"><label for="impact-plastic">Single-use plastic avoided (kg)</label><input class="vc-input" id="impact-plastic" name="plastic_avoided_kg" type="number" min="0" max="10000000" step="0.01"></div><div class="vc-field"><label for="impact-artisans">Artisans receiving orders *</label><input class="vc-input" id="impact-artisans" name="artisans_supported" type="number" min="1" max="100000" required></div><div class="vc-field full"><label for="impact-method">Measurement method, assumptions and limitations *</label><textarea class="vc-textarea" id="impact-method" name="measurement_method" required minlength="50" maxlength="1500"></textarea></div><div class="vc-field full"><label for="impact-evidence">Supporting workbook/report</label><input class="vc-input" id="impact-evidence" name="impact_evidence" type="file" accept=".csv,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" data-max-bytes="10485760"></div></div><div class="vc-form-actions"><button class="vc-btn" type="button" data-demo-action="Download impact data template">Template</button><button class="vc-btn primary" type="submit">Validate impact report</button></div></div></form></section></div>
<dialog class="vc-dialog" id="claim-dialog"><div class="vc-dialog-head"><h2>Add evidence-backed claim</h2><button class="vc-btn small" type="button" data-close-dialog>Close</button></div><form class="vc-dialog-body" data-frontend-form="sustainability-claim" data-success="Claim fields validated and ready for review."><div class="vc-form-grid"><div class="vc-field"><label for="claim-type">Claim type *</label><select class="vc-select" id="claim-type" name="claim_type" required><option value="">Select claim</option><option>Organic material</option><option>Recycled content</option><option>Upcycled material</option><option>Plastic-free</option><option>Biodegradable</option><option>Compostable</option><option>Vegan</option><option>Cruelty-free</option><option>Locally sourced</option><option>Fair/living-wage practice</option><option>Renewable energy</option><option>Low-waste production</option><option>Repairable/reusable</option><option>Other measurable claim</option></select></div><div class="vc-field"><label for="claim-scope">Scope *</label><input class="vc-input" id="claim-scope" name="scope" required maxlength="160" placeholder="Product, range, packaging or operation"></div><div class="vc-field full"><label for="claim-statement">Exact claim and qualification *</label><textarea class="vc-textarea" id="claim-statement" name="claim_statement" required minlength="20" maxlength="600"></textarea></div><div class="vc-field"><label for="evidence-type">Evidence type *</label><select class="vc-select" id="evidence-type" name="evidence_type" required><option value="">Select evidence</option><option>Third-party certificate</option><option>Laboratory report</option><option>Supplier declaration and invoices</option><option>Internal measurement with methodology</option><option>Government/industry registration</option></select></div><div class="vc-field"><label for="claim-valid-until">Evidence valid until/review date *</label><input class="vc-input" id="claim-valid-until" name="valid_until" type="date" required></div><div class="vc-field"><label for="claim-issuer">Issuer/source *</label><input class="vc-input" id="claim-issuer" name="issuer" required maxlength="160"></div><div class="vc-field"><label for="claim-number">Certificate/report/reference</label><input class="vc-input" id="claim-number" name="reference" maxlength="120"></div><div class="vc-field full"><label for="claim-file">Evidence document *</label><input class="vc-input" id="claim-file" name="evidence_file" type="file" accept="image/jpeg,image/png,application/pdf" data-max-bytes="5242880" required></div><div class="vc-field full"><label for="claim-limitations">Conditions, exclusions and limitations *</label><textarea class="vc-textarea" id="claim-limitations" name="limitations" required minlength="10" maxlength="600"></textarea></div></div><div class="vc-form-actions"><button class="vc-btn" type="button" data-close-dialog>Cancel</button><button class="vc-btn primary" type="submit">Validate claim</button></div></form></dialog>
